import type { Request, Response } from "express";
import { recordPayment } from "./payments.js";

type PaymentEvent = { kind: "payment"; id: string; amountCents: number };

export async function handleWebhook(req: Request, res: Response) {
  const event = JSON.parse(req.body) as PaymentEvent;
  await recordPayment(event.id, event.amountCents);
  res.sendStatus(204);
}

